//go:build linux

package promptskills

import (
 "context"
 "errors"
 "os"
 "path/filepath"
 "strings"
 "sync"
 "testing"
 "time"
)

func newTestService(t *testing.T)(*Service,string){t.Helper();root:=t.TempDir();s,err:=New(root);if err!=nil{t.Fatal(err)};t.Cleanup(func(){s.Close()});return s,root}
func TestPromptCRUDAndLegacyCleanup(t *testing.T){s,root:=newTestService(t);if err:=os.Mkdir(filepath.Join(root,"prompts"),0700);err!=nil{t.Fatal(err)};if err:=os.WriteFile(filepath.Join(root,"prompts","public.json"),[]byte(`{"key":"public","content":"old"}`),0600);err!=nil{t.Fatal(err)};if err:=s.SavePrompt(map[string]any{"key":"public","content":"Public 中文","extra":true});err!=nil{t.Fatal(err)};if _,err:=os.Stat(filepath.Join(root,"prompts","public.json"));!os.IsNotExist(err){t.Fatal("legacy file retained")};if err:=s.SavePrompt(map[string]any{"key":"public","writingLanguage":"en-US","content":"English"});err!=nil{t.Fatal(err)};receipt,err:=s.LoadPrompts();if err!=nil||len(receipt["templates"].([]map[string]any))!=2{t.Fatal(receipt,err)};if err=s.DeletePrompt("public","zh-CN");err!=nil{t.Fatal(err)};receipt,err=s.LoadPrompts();if err!=nil||len(receipt["templates"].([]map[string]any))!=1{t.Fatal(receipt,err)};if err=s.DeletePrompt("../outside","zh-CN");err==nil{t.Fatal("traversal accepted")};if err=s.SavePrompt(map[string]any{"key":"public","writingLanguage":nil});err==nil{t.Fatal("null language accepted")}}
func TestOwnedSymlinkHardlinkAndAncestorRefusal(t *testing.T){for _,kind:=range []string{"parent-link","file-link","hardlink","skill-link","uninstall-link"}{t.Run(kind,func(t *testing.T){s,root:=newTestService(t);outside:=t.TempDir();target:=filepath.Join(outside,"sentinel.json");if err:=os.WriteFile(target,[]byte("sentinel"),0600);err!=nil{t.Fatal(err)};var err error;switch kind {case "parent-link":if err=os.Symlink(outside,filepath.Join(root,"prompts"));err!=nil{t.Fatal(err)};err=s.SavePrompt(map[string]any{"key":"public"});case "file-link","hardlink":if err=os.Mkdir(filepath.Join(root,"prompts"),0700);err!=nil{t.Fatal(err)};destination:=filepath.Join(root,"prompts","public.zh-CN.json");if kind=="file-link"{err=os.Symlink(target,destination)}else{err=os.Link(target,destination)};if err!=nil{t.Fatal(err)};err=s.SavePrompt(map[string]any{"key":"public"});case "skill-link","uninstall-link":if err=os.Mkdir(filepath.Join(root,"skills"),0700);err!=nil{t.Fatal(err)};if err=os.Symlink(outside,filepath.Join(root,"skills","public"));err!=nil{t.Fatal(err)};if kind=="uninstall-link"{err=s.UninstallUser("public")}else{var list []UserSkill;list,err=s.ListUser();if err!=nil||len(list)!=0{t.Fatal(list,err)};err=ErrUnsafe}};if err==nil{t.Fatal("unsafe path accepted")};data,e:=os.ReadFile(target);if e!=nil||string(data)!="sentinel"{t.Fatal("outside sentinel changed",e)}})};parent:=t.TempDir();real:=t.TempDir();link:=filepath.Join(parent,"linked");if err:=os.Symlink(real,link);err!=nil{t.Fatal(err)};if _,err:=New(link);err==nil{t.Fatal("symlink root accepted")}}
func TestUserInventoryManifestIntegrity(t *testing.T){s,root:=newTestService(t);dir:=filepath.Join(root,"skills","public");if err:=os.MkdirAll(filepath.Join(dir,"references"),0700);err!=nil{t.Fatal(err)};raw:="---\nname: public\n---\nRead [ref](./references/a.md).";for name,text:=range map[string]string{"SKILL.md":raw,"references/a.md":"Public reference."}{if err:=os.WriteFile(filepath.Join(dir,name),[]byte(text),0600);err!=nil{t.Fatal(err)}};manifest:=`{"version":1,"files":[{"path":"references/a.md","sha256":"`+digest([]byte("Public reference."))+`"}]}`;if err:=os.WriteFile(filepath.Join(dir,BundleManifest),[]byte(manifest),0600);err!=nil{t.Fatal(err)};skill,err:=s.ReadUser("public");if err!=nil||skill.Bundle.Status!="intact"{t.Fatal(skill,err)};inspection:=InspectInstalled(skill.Content,skill.Bundle,skill.Name);if !inspection.Compatible||!strings.Contains(inspection.Content,"Public reference."){t.Fatal(inspection)};if err=os.WriteFile(filepath.Join(dir,"references/a.md"),[]byte("tampered"),0600);err!=nil{t.Fatal(err)};skill,err=s.ReadUser("public");if err!=nil||skill.Bundle.Status!="damaged"{t.Fatal(skill,err)};if err=s.UninstallUser("public");err!=nil{t.Fatal(err)};if _,err=os.Stat(dir);!os.IsNotExist(err){t.Fatal("skill still exists")}}

type testAuthority struct {mu sync.RWMutex;generation string;held bool}
func(a *testAuthority)AcquireCurrent(ctx context.Context,c Caller)(func(),error){a.mu.RLock();if ctx.Err()!=nil||a.generation!=c.Generation{a.mu.RUnlock();return nil,ErrInspectFirst};a.held=true;return func(){a.held=false;a.mu.RUnlock()},nil}
type testDispatch struct {calls int;raw string;blockAt int;entered chan struct{};resume chan struct{}}
func(d *testDispatch)FetchGitHub(ctx context.Context,endpoint string,limit int)(int,[]byte,error){d.calls++;if d.blockAt==d.calls{close(d.entered);select{case <-d.resume:case <-ctx.Done():return 0,nil,ctx.Err()}};if strings.HasPrefix(endpoint,"https://api.github.com/"){return 200,[]byte(`{"default_branch":"main"}`),nil};if !strings.HasPrefix(endpoint,"https://raw.githubusercontent.com/public/fixture/main/"){return 0,nil,errors.New("unexpected origin")};return 200,[]byte(d.raw),nil}
func remoteTest(t *testing.T)(*Service,string,Caller,*testAuthority,*testDispatch){t.Helper();s,root:=newTestService(t);caller:=Caller{Principal:"public-user",SessionID:"session",ClientID:"client",Generation:"generation"};authority:=&testAuthority{generation:caller.Generation};if err:=s.SetRemoteAuthority(authority);err!=nil{t.Fatal(err)};dispatch:=&testDispatch{raw:"---\nname: public\n---\nPublic prompt only."};return s,root,caller,authority,dispatch}
func TestRemoteReceiptsCallerExpiryOneUseAndChanged(t *testing.T){for _,variant:=range []string{"foreign-client","foreign-session","foreign-principal","foreign-generation","expired","changed","stale-generation","success"}{t.Run(variant,func(t *testing.T){s,root,c,a,d:=remoteTest(t);source:="https://github.com/public/fixture/blob/main/SKILL.md";if _,err:=s.InspectGitHub(context.Background(),c,source,d);err!=nil{t.Fatal(err)};switch variant{case "foreign-client":c.ClientID="other";case "foreign-session":c.SessionID="other";case "foreign-principal":c.Principal="other";case "foreign-generation":c.Generation="other";case "expired":s.mu.Lock();r:=s.receipts[receiptKey{c,source}];r.Expires=time.Now().Add(-time.Second);s.receipts[receiptKey{c,source}]=r;s.mu.Unlock();case "changed":d.raw+="changed";case "stale-generation":a.generation="next"};_,err:=s.InstallGitHub(context.Background(),c,source,d);if variant=="success" {if err!=nil{t.Fatal(err)};if _,err=s.InstallGitHub(context.Background(),c,source,d);!errors.Is(err,ErrInspectFirst){t.Fatal("receipt reused",err)}}else {if err==nil{t.Fatal("invalid receipt accepted")};if _,err=os.Stat(filepath.Join(root,"skills"));!os.IsNotExist(err){t.Fatal("rejected receipt mutated directory",err)}}})}}
func TestCloseAndCancellationDuringRefetchCannotPublish(t *testing.T){for _,variant:=range []string{"close","cancel","generation"}{t.Run(variant,func(t *testing.T){s,root,c,a,d:=remoteTest(t);source:="https://github.com/public/fixture/blob/main/SKILL.md";if _,err:=s.InspectGitHub(context.Background(),c,source,d);err!=nil{t.Fatal(err)};d.blockAt=d.calls+1;d.entered=make(chan struct{});d.resume=make(chan struct{});ctx,cancel:=context.WithCancel(context.Background());defer cancel();result:=make(chan error,1);go func(){_,err:=s.InstallGitHub(ctx,c,source,d);result<-err}();<-d.entered;switch variant{case "close":if err:=s.Close();err!=nil{t.Fatal(err)};case "cancel":cancel();case "generation":a.mu.Lock();a.generation="next";a.mu.Unlock()};close(d.resume);if err:=<-result;err==nil{t.Fatal("lifecycle change published installation")};if _,err:=os.Stat(filepath.Join(root,"skills"));!os.IsNotExist(err){t.Fatal("lifecycle failure mutated filesystem",err)};if variant=="close"{if _,err:=s.LoadPrompts();!errors.Is(err,ErrClosed){t.Fatal(err)};if err:=s.SavePrompt(map[string]any{"key":"public"});!errors.Is(err,ErrClosed){t.Fatal(err)};if _,err:=s.ListUser();!errors.Is(err,ErrClosed){t.Fatal(err)};if err:=s.UninstallUser("public");!errors.Is(err,ErrClosed){t.Fatal(err)}}})}}
func TestRemoteDisabledWithoutExplicitAuthorityAndDispatch(t *testing.T){s,_:=newTestService(t);c:=Caller{Principal:"p",SessionID:"s",ClientID:"c",Generation:"g"};if _,err:=s.InspectGitHub(context.Background(),c,"https://github.com/public/fixture",nil);!errors.Is(err,ErrRemoteUnavailable){t.Fatal(err)}}
